/**
 * @name Unsafe URL parsing leading to SSRF or injection
 * @description URL parsing vulnerabilities in urllib3 could allow SSRF attacks or injection
 * @kind path-problem
 * @problem.severity error
 * @id py/unsafe-url-parsing
 * @tags security
 *        external/cwe/cwe-918
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module UrlParsingConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // Look for URL parsing operations that could be vulnerable
    exists(DataFlow::CallCfgNode call |
      sink = call.getArg(0) and
      (
        call = API::moduleImport("urllib3").getMember("parse_url").getACall() or
        call = API::moduleImport("urllib").getMember("parse").getMember(["urlparse", "urljoin", "urlsplit"]).getACall() or
        call = API::moduleImport("urllib3").getMember("util").getMember("url").getMember("parse_url").getACall()
      )
    )
  }
}

module UrlParsingFlow = TaintTracking::Global<UrlParsingConfig>;
import UrlParsingFlow::PathGraph

from UrlParsingFlow::PathNode source, UrlParsingFlow::PathNode sink
where UrlParsingFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Unsafe URL parsing from $@.", source.getNode(), "user input"

/**
 * @name HTTP header injection (CRLF injection)
 * @description CRLF injection in HTTP headers can lead to request smuggling or response splitting
 * @kind path-problem
 * @problem.severity error
 * @id py/http-header-injection
 * @tags security
 *        external/cwe/cwe-113
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
