module HeaderInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // Look for HTTP header setting operations
    exists(DataFlow::CallCfgNode call |
      sink = call.getArg(0) and
      (
        // urllib3 header setting methods
        call = API::moduleImport("urllib3").getMember(["request", "urlopen", "HTTPConnection", "HTTPSConnection"]).getMember(["putheader", "add_header", "set_header"]).getACall() or
        // requests library header setting
        call = API::moduleImport("requests").getMember(["get", "post", "put", "delete", "head", "patch", "request"]).getMember(["headers"]).getACall()
      )
    )
  }
}

