/**
 * @name Path traversal vulnerability
 * @description Path traversal in file operations could allow access to sensitive files
 * @kind path-problem
 * @problem.severity error
 * @id py/path-traversal
 * @tags security
 *        external/cwe/cwe-022
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module PathTraversalConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // Look for file system operations
    exists(DataFlow::CallCfgNode call |
      sink = call.getArg(0) and
      (
        // File open operations
        call = API::moduleImport("builtins").getMember("open").getACall() or
        call = API::moduleImport("os").getMember(["open", "chdir", "remove", "unlink", "rename", "stat", "listdir"]).getACall() or
        call = API::moduleImport("os.path").getMember(["join", "exists", "isfile", "isdir"]).getACall() or
        call = API::moduleImport("pathlib").getMember("Path").getACall() or
        // urllib3 file operations
        call = API::moduleImport("urllib3").getMember(["filepost", "fields"]).getMember(["encode_multipart_formdata", "encode"]).getACall()
      )
    )
  }
}

